select pg_temp.check('same-play passing and receiving sums reconcile','INTEGRITY',pg_temp.ff_stats('oracle','primary')->>'passing_yards'='105'and pg_temp.ff_stats('oracle','primary')->>'receiving_yards'='105'and pg_temp.ff_stats('oracle','opponent')->>'passing_yards'='35'and pg_temp.ff_stats('oracle','opponent')->>'receiving_yards'='35');
