select pg_temp.check('one immutable Football epoch seals sixteen rows','FINALIZATION',(select count(*)=1 from public.game_football_finalizations where game_id=pg_temp.ff_game('oracle'))and(select count(*)=16 from public.game_football_final_stats where game_id=pg_temp.ff_game('oracle')));
select pg_temp.check('Football epoch reuses canonical Game Center seal','FINALIZATION',not exists(select 1 from public.game_football_finalizations f left join public.game_finalizations c on c.id=f.finalization_id where f.game_id=pg_temp.ff_game('oracle')and(c.id is null or f.epoch<>c.epoch or f.roster_revision<>c.roster_revision or f.organization_id<>c.organization_id)));
select pg_temp.check('sealed athlete rows retain persistent snapshot provenance','PROVENANCE',(select count(*)=14 from public.game_football_final_stats f join public.game_roster_snapshots r on r.id=f.roster_id join public.game_football_finalizations e on e.finalization_id=f.finalization_id where f.game_id=pg_temp.ff_game('oracle')and r.game_id=f.game_id and r.revision=e.roster_revision and r.organization_id=f.organization_id and r.person_id is not null and r.participant_id is not null));
