select pg_temp.game_op('game.reopen','oracle','{"reason":"Synthetic authorized XP correction"}');
select pg_temp.ff_op('football.play.correct','oracle',jsonb_build_object('event_id',pg_temp.ff_event_id('oracle','oracle-p29'),'reason','Synthetic made-to-missed XP correction','play_type','extra_point','side','primary','roster_id',pg_temp.ff_roster('oracle','primary',7),'made',false),'oracle-correct29');
select pg_temp.game_op('game.finalize','oracle');
reset role;
select pg_temp.check('independent E2 score24-16','ORACLE',(select status='final'and primary_score=24 and opponent_score=16 and final_primary_score=24 and final_opponent_score=16 from public.games where id=pg_temp.ff_game('oracle')));
update ff_literal_oracle set expected=expected||'{"points":24,"extra_points_made":1}'where side='primary'and n=0;
update ff_literal_oracle set expected=expected||'{"points":4,"extra_points_made":1}'where side='primary'and n=7;
do $$declare e record;begin for e in select *from ff_literal_oracle loop perform pg_temp.ff_expect('oracle',e.side,e.n,e.expected,'E2 literal '||e.side||'/'||e.n);end loop;end$$;
select pg_temp.check('prior Football epoch byte-identical after correction','FINALIZATION',not exists((select row from ff_epoch1_frozen)except(select to_jsonb(f)from public.game_football_final_stats f join public.game_football_finalizations e using(finalization_id)where f.game_id=pg_temp.ff_game('oracle')and e.epoch=1)));
select pg_temp.check('refinalization appends epoch2 and sixteen new rows','FINALIZATION',(select count(*)=2 and max(epoch)=2 from public.game_football_finalizations where game_id=pg_temp.ff_game('oracle'))and(select count(*)=32 from public.game_football_final_stats where game_id=pg_temp.ff_game('oracle')));
select pg_temp.check('original receiver and XP facts remain immutable','CORRECTION',(select payload->>'receiver_roster_id'=pg_temp.ff_roster('oracle','primary',3)::text from public.game_football_events where id=pg_temp.ff_event_id('oracle','oracle-p34'))and(select(payload->>'made')::boolean from public.game_football_events where id=pg_temp.ff_event_id('oracle','oracle-p29')));
select pg_temp.check('corrections retain origin period/clock coordinates','CORRECTION',not exists(select 1 from public.game_football_events c join public.game_football_events e on e.id=c.correction_of where c.game_id=pg_temp.ff_game('oracle')and(c.origin_sequence<>e.origin_sequence or c.period_number<>e.period_number or c.clock_ms<>e.clock_ms)));
select pg_temp.check('complete canonical ledger has no duplicate sequences','LEDGER',(select count(*)=max(sequence)and min(sequence)=1 and count(distinct version)=count(*)from public.game_operations where game_id=pg_temp.ff_game('oracle')));
select pg_temp.check('Football plays do not fan out per-play notifications','NOTIFICATIONS',not exists(select 1 from public.notification_events n join public.game_operations o on o.id=n.source_id where o.game_id=pg_temp.ff_game('oracle')and o.operation like 'football.%'and o.operation<>'football.period.end'));
select count(*)as passed_assertions,category from pg_temp.phase5a_assertions group by category order by category;
rollback;
